    {
        SELECT ?action ?currentAllocationPct ?targetAllocationPct
        WHERE {
            ?action a ex:RebalancingAction ;
                    ex:currentAllocationPct ?currentAllocationPct ;
                    ex:targetAllocationPct ?targetAllocationPct .
        }
