PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?liquidityScore)) AS ?averageLiquidityRating)
WHERE {
    # Subquery to identify investors whose total withdrawal transactions exceed 50,000
    {
        SELECT ?investor WHERE {
            ?cashflow ex:hasInvestor ?investor .
            ?cashflow ex:amount ?amount ;
                      ex:cashFlowType "Withdrawal" . 
        }
        GROUP BY ?investor
        HAVING (SUM(xsd:decimal(?amount)) > 50000)
    }

    # Main query joins the filtered investors to their Portfolio Health records
    ?ph ex:hasInvestor ?investor ;
          ex:liquidityScore ?liquidityScore .
}

