PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?currentValue ?investorName
WHERE {
    # 1. Identify Investors who have NEVER recorded a 'redemption' cash flow (Negative Constraint)
    {
        ?investor a ex:InvestorProfile .
        FILTER NOT EXISTS {
            ?cf a ex:CashFlow ;
                 ex:hasInvestor ?investor ;
                 ex:cashFlowType ?cft .
            # Filter for cash flow type being 'redemption' (case-insensitive)
            FILTER(LCASE(STR(?cft)) = "redemption")
        }
    }

    # 2. Find holdings associated with these qualified investors
    ?holding ex:hasInvestor ?investor .

    # 3. Filter the holding to ensure it is a 'mutual fund' type
    ?holding ex:investmentTypeLiteral ?invTypeLiteral .
    FILTER(LCASE(STR(?invTypeLiteral))) = "mutual fund" .

    # 4. Select required details from the holding and investor
    ?holding ex:holdingId ?holdingId ;
             ex:investmentName ?investmentName ;
             ex:currentValue ?currentValue .

    ?investor ex:investorName ?investorName .
}

