PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName
WHERE {
    # Calculate the total dividends for each investor across all their holdings.
    {
        SELECT ?investor (SUM(?dividend) AS ?totalDividends)
        WHERE {
            ?holding ex:hasInvestor ?investor .
            BIND(COALESCE(xsd:decimal(?holding dividends), 0) AS ?dividend)
        }
}
GROUP BY ?investor

    # Filter for investors whose total dividends sum to zero.
    FILTER (?totalDividends = 0)

    # Retrieve the name of the investor who meets the criteria.
    ?investor ex:investorName ?investorName .
}

