PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?date ?amount ?cashFlowType
WHERE {
  ?cashFlow a ex:CashFlow ;
             ex:date ?date ;
             ex:amount ?amount ;
             ex:cashFlowType ?cashFlowType .

  # Filter for Dividend cash flow events (case-insensitive)
  FILTER(CONTAINS(LCASE(STR(?cashFlowType)), "dividend"))

  # Calculate the date 6 months ago and filter records newer than that.
  BIND(NOW() - "P6M"^^xsd:temporalLiteral AS ?sixMonthsAgo)
  FILTER(?date >= ?sixMonthsAgo)
}

