SELECT (COUNT(DISTINCT ?investor) AS ?totalInvestors)
WHERE {
    {
        # Calculate the total taxes paid for each investor
        SELECT ?investor (SUM(?taxValue) AS ?totalTaxes)
        WHERE {
            ?holding ex:hasInvestor ?investor .
            ?holding ex:taxesPaid ?taxValue .
        }
        GROUP BY ?investor
        # Filter groups where the total taxes exceed 500,000
        HAVING (?totalTaxes > 500000)
    }
}

