PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName 
       (SUM{
           SELECT ?amount WHERE {
               ?cf ex:hasInvestor ?investor .
               ?cf ex:amount ?amount ;
                    ex:cashFlowType "Deposit" . # Assuming 'Deposit' is the literal type for deposits
           }
       } AS ?totalDeposits)
       (SUM{
           SELECT ?amount WHERE {
               ?cf ex:hasInvestor ?investor .
               ?cf ex:amount ?amount ;
                    ex:cashFlowType "Withdrawal" . # Assuming 'Withdrawal' is the literal type for withdrawals
           }
       } AS ?totalWithdrawals)
       BIND(COALESCE(IF(?totalDeposits = 0, NULL, ?totalWithdrawals / ?totalDeposits), NULL) AS ?withdrawalToDepositRatio)
WHERE {
    # Get investor name to group by
    ?investor schema1:investorName ?investorName .
}
GROUP BY ?investorName
HAVING (COUNT(?cf) > 0)
